 "content": "def transform(grid):
    h = len(grid) // 4
    w = len(grid[0])
    out = [[0] * w for _ in range(h)]
    # Overlay the 2, 4, and 5 panels; higher-valued marks win.
    for color, panel in ((2, 2), (4, 1), (5, 0)):
        for r in range(h):
            for c in range(w):
                if grid[panel * h + r][c] == color:
                    out[r][c] = color
    # The bottom 8 panel marks cells to remove from the composition.
    for r in range(h):
        for c in range(w):
            if grid[3 * h + r][c] == 8:
                out[r][c] = 0
    return out

